<?php
require_once __DIR__.'/identity.php';
function account_register(array $b,bool $professional=false): array {rate('register',10,3600);$email=strtolower(text_field($b,'email',190,true));$password=text_field($b,'password',200,true);if(!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<12)fail(422,'account','Email valide et mot de passe de 12 caractères minimum requis.','أدخل بريدًا صالحًا وكلمة مرور من 12 حرفًا على الأقل.');$exists=one('SELECT * FROM users WHERE email=?',[$email]);if($exists){$u=actor();if($u&&(int)$u['id']===(int)$exists['id'])return ['user'=>$u,'csrf'=>csrf()];fail(409,'email_exists','Ce compte existe déjà. Connectez-vous.','الحساب موجود. سجّل الدخول.');}
 $u=tx(function()use($b,$email,$password,$professional){q('INSERT INTO users(email,password_hash,role,language) VALUES(?,?,?,?)',[$email,password_hash($password,PASSWORD_DEFAULT),$professional?'professional':'customer',lang()]);$id=(int)db()->lastInsertId();if($professional){$profession=enum_field($b,'profession',['veterinarian','groomer','trainer','breeder','pet_shop','shelter','other']);if(!$profession)fail(422,'profession','Métier requis.');q('INSERT INTO professional_profiles(user_id,business_name,profession,profession_other,phone,city) VALUES(?,?,?,?,?,?)',[$id,text_field($b,'business_name',150,true),$profession,text_field($b,'profession_other',100),text_field($b,'phone',30,true),text_field($b,'city',100,true)]);}return one('SELECT * FROM users WHERE id=?',[$id]);});login_user($u);return ['user'=>actor(true),'csrf'=>csrf()];
}
function account_login(array $b): array {rate('login',10,600);$email=strtolower(text_field($b,'email',190,true));$password=text_field($b,'password',200,true);$u=one('SELECT * FROM users WHERE email=?',[$email]);$dummy='$2y$10$92IXUNpkjO0rOQ5byMi.Ye4oKoEa3Ro9llC/.og/at2uheWG/igi.';$valid=password_verify($password,$u['password_hash']??$dummy);if(!$valid||!$u||$u['status']!=='active'||($u['is_demo']&&!cfg('ALLOW_DEMO',false)))fail(401,'login','Identifiants incorrects ou compte indisponible.','بيانات الدخول غير صحيحة أو الحساب غير متاح.');login_user($u);return ['user'=>actor(true),'csrf'=>csrf()];}
function reset_request(array $b): array {rate('reset',5,900);if(!cfg('EMAIL_ENABLED',false)||!filter_var(cfg('EMAIL_FROM',''),FILTER_VALIDATE_EMAIL))fail(503,'email_unavailable','La récupération par email est indisponible. Contactez PETICA.','استعادة الحساب بالبريد غير متاحة. تواصل مع PETICA.');$email=strtolower(text_field($b,'email',190,true));if(!filter_var($email,FILTER_VALIDATE_EMAIL))fail(422,'email','Email invalide.');$u=one('SELECT id FROM users WHERE email=? AND status="active"',[$email]);if($u){$token=bin2hex(random_bytes(32));q('INSERT INTO password_reset_tokens(user_id,token_hash,expires_at) VALUES(?,?,DATE_ADD(UTC_TIMESTAMP(),INTERVAL 30 MINUTE))',[$u['id'],hash('sha256',$token)]);$link=APP_URL.'/'.lang().'/auth/reset-password.html?token='.$token;if(!mail($email,'PETICA — accès au compte',$link,['From'=>cfg('EMAIL_FROM')])){q('DELETE FROM password_reset_tokens WHERE token_hash=?',[hash('sha256',$token)]);fail(503,'email_unavailable','Le transport email est indisponible.');}}return ['message'=>tr('Si un compte correspond, un lien de récupération a été transmis au service email.','إذا كان الحساب موجودًا، تم تمرير رابط الاستعادة إلى خدمة البريد.')];}
function reset_confirm(array $b): array {$pw=text_field($b,'password',200,true);if(strlen($pw)<12)fail(422,'password','12 caractères minimum.');return tx(function()use($b,$pw){$r=one('SELECT * FROM password_reset_tokens WHERE token_hash=? AND used_at IS NULL AND expires_at>UTC_TIMESTAMP() FOR UPDATE',[hash('sha256',(string)($b['token']??''))]);if(!$r)fail(422,'token','Lien expiré ou déjà utilisé.','الرابط منتهي أو مستخدم.');q('UPDATE users SET password_hash=?,auth_version=auth_version+1 WHERE id=?',[password_hash($pw,PASSWORD_DEFAULT),$r['user_id']]);q('UPDATE password_reset_tokens SET used_at=UTC_TIMESTAMP() WHERE user_id=? AND used_at IS NULL',[$r['user_id']]);return ['message'=>tr('Mot de passe modifié. Reconnectez-vous.','تم تغيير كلمة المرور. سجّل الدخول مجددًا.')];});}
function pro_profile_save(array $b,array $u): array {$p=one('SELECT * FROM professional_profiles WHERE user_id=?',[$u['id']]);if(!$p)fail(404,'profile','Profil professionnel introuvable.');$profession=enum_field($b,'profession',['veterinarian','groomer','trainer','breeder','pet_shop','shelter','other']);q('UPDATE professional_profiles SET business_name=?,profession=?,profession_other=?,phone=?,city=?,verification_status="pending",verified_at=NULL,verified_by=NULL WHERE user_id=?',[text_field($b,'business_name',150,true),$profession,text_field($b,'profession_other',100),text_field($b,'phone',30,true),text_field($b,'city',100,true),$u['id']]);audit('professional.updated','professional',(int)$p['id']);return ['profile'=>one('SELECT * FROM professional_profiles WHERE user_id=?',[$u['id']])];}
function pro_relation_request(array $b,array $u): array {pro_approved($u);rate('relation',10,3600);$email=strtolower(text_field($b,'email',190,true));$client=one('SELECT id FROM users WHERE email=? AND role="customer" AND status="active" AND is_demo=0',[$email]);if($client)tx(function()use($client,$u){q('INSERT IGNORE INTO professional_clients(professional_user_id,customer_user_id,consent_status) VALUES(?,?,"pending")',[$u['id'],$client['id']]);$r=one('SELECT * FROM professional_clients WHERE professional_user_id=? AND customer_user_id=?',[$u['id'],$client['id']]);if($r['consent_status']==='revoked')q('UPDATE professional_clients SET consent_status="pending" WHERE id=?',[$r['id']]);notify((int)$client['id'],'professional_request','Demande de relation professionnelle','طلب ربط مع مهني.','relationship',(int)$r['id']);});return ['message'=>tr('Si le compte existe, la demande est disponible dans son espace.','إذا كان الحساب موجودًا، فالطلب متاح في مساحته.')];}
function relation_confirm(int $id,array $b,array $u): array {$r=one('SELECT * FROM professional_clients WHERE id=? AND customer_user_id=?',[$id,$u['id']]);if(!$r)fail(403,'relationship','Relation non autorisée.');$state=enum_field($b,'consent_status',['accepted','revoked']);$scopes=['identity'];$pro=one('SELECT profession FROM professional_profiles WHERE user_id=?',[$r['professional_user_id']]);if(checked($b['medical']??0)&&$pro&&$pro['profession']==='veterinarian')$scopes[]='medical';q('UPDATE professional_clients SET consent_status=?,scopes=?,consented_at=UTC_TIMESTAMP() WHERE id=?',[$state,implode(',',$scopes),$id]);audit('relationship.'.$state,'relationship',$id);return ['relationship'=>one('SELECT id,consent_status,scopes FROM professional_clients WHERE id=?',[$id])];}
function visit_save(int $cid,array $b,array $u,bool $medical=false): array {$p=pro_approved($u);allow_companion($cid,$u,$medical?'medical':'identity');if($medical&&$p['profession']!=='veterinarian')fail(403,'medical','Acte vétérinaire non autorisé.');return once($u,$medical?'vet:create':'visit:create',$b,function()use($cid,$b,$u,$medical,$p){$date=text_field($b,'visit_date',10,true);$dt=DateTimeImmutable::createFromFormat('!Y-m-d',$date);if(!$dt||$dt->format('Y-m-d')!==$date||$date>gmdate('Y-m-d'))fail(422,'date','Date invalide.');if($medical){q('INSERT INTO veterinary_records(companion_id,clinic_name,visit_date,reason,diagnosis,treatment,notes,created_by) VALUES(?,?,?,?,?,?,?,?)',[$cid,$p['business_name'],$date,text_field($b,'reason',255,true),text_field($b,'diagnosis',6000),text_field($b,'treatment',6000),text_field($b,'notes',6000),$u['id']]);}else{q('INSERT INTO session_notes(companion_id,professional_user_id,session_type,session_date,note,recommendation,follow_up_date) VALUES(?,?,?,?,?,?,?)',[$cid,$u['id'],enum_field($b,'session_type',['consultation','training','grooming','breeding','observation','other'],'consultation'),$date.' 12:00:00',text_field($b,'reason',255,true).' — '.text_field($b,'notes',6000),text_field($b,'recommendation',2000),text_field($b,'follow_up_date',10)]);}$recordId=(int)db()->lastInsertId();audit($medical?'vet.created':'visit.created','companion',$cid);return ['record_id'=>$recordId];});}
